import re


def eval_expression(expr):
    # 空白を削除
    expr = expr.replace(" ", "")

    # トークナイザー（数値、演算子、括弧に分解）
    # 負の数に対応するため、マイナスが演算子として働くか符号として働くかを考慮します
    tokens = re.findall(r"(?:\d+(?:\.\d*)?|\.\d+|[+\-*/()]?)", expr)
    tokens = [t for t in tokens if t != ""]

    class Parser:

        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, expected=None):
            token = self.peek()
            if expected and token != expected:
                raise ValueError(f"Expected '{expected}', got '{token}'")
            self.pos += 1
            return token

        def parse(self):
            if not self.tokens:
                return 0
            result = self.expr()
            if self.pos < len(self.tokens):
                raise ValueError(f"Unexpected token: {self.peek()}")
            return result

        # 加算・減算 (優先順位 低)
        def expr(self):
            result = self.term()
            while self.peek() in ("+", "-"):
                op = self.consume()
                if op == "+":
                    result += self.term()
                elif op == "-":
                    result -= self.term()
            return result

        # 乗算・除算 (優先順位 中)
        def term(self):
            result = self.factor()
            while self.peek() in ("*", "/"):
                op = self.consume()
                if op == "*":
                    result *= self.factor()
                elif op == "/":
                    divisor = self.factor()
                    if divisor == 0:
                        raise ZeroDivisionError("division by zero")
                    result /= divisor
            return result

        # 括弧、単項マイナス、数値 (優先順位 高)
        def factor(self):
            token = self.peek()

            # 単項マイナス（負の数）の処理
            if token == "-":
                self.consume("-")
                return -self.factor()
            if token == "+":
                self.consume("+")
                return self.factor()

            # 括弧の処理
            if token == "(":
                self.consume("(")
                result = self.expr()
                self.consume(")")
                return result

            # 数値の処理
            if token is not None:
                self.consume()
                try:
                    # 小数点が含まれていれば float、なければ int に変換
                    if "." in token:
                        return float(token)
                    else:
                        return int(token)
                except ValueError:
                    raise ValueError(f"Invalid number: {token}")

            raise ValueError("Unexpected end of expression")

    parser = Parser(tokens)
    return parser.parse()


# --- 使用例・テスト ---
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))  # 出力: 7
    print(eval_expression("-5 + 3 * (-2)"))  # 出力: -11 (負の数に対応)
    print(eval_expression("10 / (5 - 5)"))  # ZeroDivisionError が発生
